  const resolved = await resolveReviewContext({
    commitish: 'HEAD',
    projectRoot: '.',
    lastCheckpoints,
    signal: options.signal,
    onProgress: (event) => emitEvent({
      type: 'stage',
      stage: event.stage,
      state: event.state,
      label: event.label,
      detail: event.detail,
    }),
  });
