  // review instead of aborting and leaving startup artifacts unattached.
  abortBeforeReviewCreation = false;

  await emitEvent({
    type: 'stage',
    stage: 'review_creation',
    state: 'active',
    label: policyMode === 'review' ? 'Creating policy review' : 'Creating review',
