    reviewId: derived.reviewId,
    routePath: buildStudioReviewRoutePath({
      reviewId: derived.reviewId,
      route: 'reports',
      repo: resolved.resolvedProvenance.repo,
      branch: resolved.resolvedProvenance.branch,
